package happy.coding.io;

import org.apache.log4j.Level;
import org.apache.log4j.PropertyConfigurator;
import org.apache.log4j.xml.DOMConfigurator;
import org.junit.Test;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Apply delegate mode
 * 
 * @author guoguibing
 * 
 */
public class Logs {
	private final static Logger logger = LoggerFactory.getLogger(Logs.class);
	private static String conf = null;

	// default configuration
	static {
		if ((conf = FileIO.getResource("log4j.properties")) != null)
			config(conf, false);
		else if ((conf = FileIO.getResource("log4j.xml")) != null)
			config(conf, true);
	}

	public static Logger config(String config, boolean isXml) {
		if (isXml)
			DOMConfigurator.configure(config);
		else
			PropertyConfigurator.configure(config);

		return logger;
	}

	public static void debug(double data) {
		logger.debug(Strings.toString(data));
	}

	public static void debug(Object msg) {
		logger.debug(msg.toString());
	}

	public static void debug(String msg) {
		logger.debug(msg);
	}

	public static void debug(String format, Object arg) {
		logger.debug(format, arg);
	}

	public static void debug(String format, Object... args) {
		logger.debug(format, args);
	}

	public static void debug() {
		debug("");
	}

	public static void error() {
		error("");
	}

	public static void warn() {
		warn("");
	}

	public static void info() {
		info("");
	}

	public static void info(double data) {
		logger.info(Strings.toString(data));
	}

	public static void info(Object msg) {
		if (msg == null)
			logger.info("");
		else
			logger.info(msg.toString());
	}

	public static void info(String format, Object arg) {
		logger.info(format, arg);
	}

	public static void info(String format, Object... args) {
		logger.info(format, args);
	}

	public static void error(double data) {
		logger.error(Strings.toString(data));
	}

	public static void error(Object msg) {
		logger.error(msg.toString());
	}

	public static void warn(String msg) {
		logger.warn(msg);
	}

	public static void warn(String format, Object arg) {
		logger.warn(format, arg);
	}

	public static void warn(String format, Object... args) {
		logger.warn(format, args);
	}

	public static void warn(double data) {
		logger.warn(Strings.toString(data));
	}

	public static void warn(Object msg) {
		logger.warn(msg.toString());
	}

	public static void error(String msg) {
		logger.error(msg);
	}

	public static void error(String format, Object arg) {
		logger.error(format, arg);
	}

	public static void error(String format, Object... args) {
		logger.error(format, args);
	}

	public static void off() {
		org.apache.log4j.Logger.getRootLogger().setLevel(Level.OFF);
	}

	public static void on() {
		org.apache.log4j.Logger.getRootLogger().setLevel(Level.DEBUG);
	}

	@Test
	public void example() {
		String[] msgs = new String[] { "Section content: ", "@author guoguibing" };

		debug(msgs);
	}

}

package malachite.gfx;

import java.util.HashMap;
import java.util.Map;

import malachite.gfx.shaders.Uniform;

import org.lwjgl.opengl.GL11;
import org.lwjgl.opengl.GL20;
import org.lwjgl.util.vector.Vector4f;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public abstract class Program {
  private static final Logger logger = LoggerFactory.getLogger(Program.class);

  private static int _current;
  public static void clear() {
    if(_current != 0) {
      _current = 0;
      GL20.glUseProgram(0);
    }
  }

  public final int id;

  private final Map<String, Uniform> _uniforms = new HashMap<>();

  protected Program(int id) {
    this.id = id;
  }

  public Uniform getUniform(String name) {
    return _uniforms.get(name);
  }

  public int getUniformLocation(String name) {
    return GL20.glGetUniformLocation(id, name);
  }

  public void addUniform(Uniform uniform) {
    _uniforms.put(uniform.name, uniform);
    uniform.bind(this);
  }

  public <T> void setUniform(int id, T value) {
    if(value instanceof Float) {
      GL20.glUniform1f(id, (float)value);
    } else if(value instanceof Vector4f) {
      Vector4f vec = (Vector4f)value;
      GL20.glUniform4f(id, vec.x, vec.y, vec.z, vec.w);
    }
  }

  public void use() {
    if(_current != id) {
      _current = id;
      GL20.glUseProgram(id);

      int error = GL11.glGetError();
      if(error != GL11.GL_NO_ERROR) {
        logger.error("Error using shader {}:\n{}", Integer.valueOf(error), getError()); //$NON-NLS-1$
      }
    }
  }

  public String getError() {
    int size = GL20.glGetProgrami(id, GL20.GL_INFO_LOG_LENGTH);
    return GL20.glGetProgramInfoLog(id, size);
  }
}
